import {
  AccordionItems,
  AccordionTitle,
  AccordionData,
  AccDetailKey,
  AccordionHeading2,
} from "./index.style";

const Accordion = ({heading, title, data = [], index }) => {
  
  const renderComponent = (acc, index) => {
    return (
      <AccordionData>
        <AccDetailKey>{`${String.fromCharCode(65 + index).toLowerCase()}. ${acc}`} </AccDetailKey>              
      </AccordionData>
    );
  };

  return (
    <AccordionItems>
      <div>  
      <AccordionHeading2>
        {`${index + 1}. ${heading}`}
      </AccordionHeading2>
      <AccordionTitle>
        {title}
        {data?.length && data?.map((acc, index) => renderComponent(acc, index))}
      </AccordionTitle>
      </div>
    </AccordionItems>
  );
};
export default Accordion;
