import { useHistory, useParams } from "react-router"
import {
    ProfileItemStyle,
    Hr,
    ProfileContentCol,
    BtnContainerStyle,
    CustomerNoteStyle,
    Footer,
    DisplayFlexCCC,
    DisplayFlexRow,
    PremiumnCal,
    TotalPreCal,
    Hr1,
    DisplayFlexPP,
    QuoteId,
    MitraHeaderLogo,
    ButtonLogo,
} from "./index.style"

import {
    resetError,
    useErrorContextValue,
    useLoaderContextValue,
} from "@pasarpolis/common-react-hooks"
import { useEffect } from "react"
import { useGetCustomerEwDetails, useGetEwDraftDownloadPdfReq } from "../../../state/hooks/useExtendedWarrantyState"
import { NEW_ARROW_RIGHT, NEW_DOWNLOAD_ICON, OJK_PP_BLACK, QS_LOGO_PP } from "../../../../../../images"
import { Grid } from "../../../../../../commonStyle/index.style"
import { Button, CustomText } from "../../../../../../components"
import { AgentColorPallette } from "../../../../../../configs/colorPallete"
import { LANG_STRINGS } from "../../../../../../lang"
import { formatMoney } from "../../../../../../helpers/utility"
import AccordionComponent from "../../../../../../components/EwQuoteAccordion"
import { CardHeaderCtn, CardHeading, CardHeading2, ImageCtn } from "../../InsuredPackage/Components/PackageList/index.style"
import { downloadFile } from "../../../../../../helpers/mitraUtils/mitra-utility"


export const getAgentDetails = (getCustomerEwDetailsData) => [
    {
        name: "NAMA LENGKAP",
        value: getCustomerEwDetailsData?.agent_info?.name,
    },
    {
        name: "AGEN ID",
        value: getCustomerEwDetailsData?.agent_info?.agent_code,
    },
    {
        name: "PONSEL",
        value: getCustomerEwDetailsData?.agent_info?.phone_no,
    },
]

export const getCarDetails = (getCustomerEwDetailsData) => [
    {
        name: "Tahun Kendaraan",
        value: getCustomerEwDetailsData?.policy_details?.year,
    },
    {
        name: "Merek Kendaraan",
        value: getCustomerEwDetailsData?.policy_details?.brand,
    },
    {
        name: "Model Kendaraan",
        value: getCustomerEwDetailsData?.policy_details?.model_data?.model_name,
    },
]

export const getProductDetails = (getCustomerEwDetailsData) => [
    {
        name: "Paket Asuransi",
        value: 'TAP Extended Warranty',
    },
    {
        name: "Premi / 12 Bulan",
        value: formatMoney(
            getCustomerEwDetailsData?.policy_details?.package_data
                ?.total_sum_insured,
            0,
            "Rp"
        ),
    },
    {
        name: "Periode Perlindungan",
        value: '12 Bulan dari tanggal polis aktif atau kendaraan telah melakukan perjalanan sejauh 50.000 km dari tanggal polis aktif.',
    },
]

export const CUSTOMER_NOTE = [
    "Pengajuan via online",
    "Layanan Call Center 24 jam",
    "Apabila terdapat perbedaan data pada penawaran (QS) dengan sertifikat polis (SCP), maka akan mengacu kepada regulasi OJK.",
]

function PolicyDocumentDetails() {
    const { id } = useParams()
    const history = useHistory()
    const [
        { getDownloadEwDraftPdfData = {} },
        getEwDraftDownloadPdfReq,
    ] = useGetEwDraftDownloadPdfReq()
    const [
        { getDownloadEwDraftPdfStatus },
        dispatchError,
    ] = useErrorContextValue()
    const [
        { getCustomerEwDetailsData = {} },
        getCustomerEwDetailsReq,
    ] = useGetCustomerEwDetails()

    useEffect(() => {
        if (id) {
            getCustomerEwDetailsReq({ draftQuoteId: id })
        }
    }, [getCustomerEwDetailsReq, id])
    const benefitsData =
        getCustomerEwDetailsData?.policy_details?.package_data?.benefit_data?.data
    const props =
        getCustomerEwDetailsData?.policy_details?.package_data

    const activeTabData = {
        Manfaat: benefitsData || [],
    }

    const renderProfileAgCards = (list, title) => {
        return (
            <>
                <CustomText
                    color={AgentColorPallette.ppBlue}
                    weight={700}
                    size="15px"
                >
                    {title}
                </CustomText>
                <ProfileContentCol>
                    <Grid
                        gridColumn="1fr 1fr"
                        gridGap="space-between"
                        className="action-grid"
                    >
                        {list.map((item, index) => (
                            <ProfileItemStyle
                                border={index + 1 !== list?.length}
                                key={index}
                            >
                                <DisplayFlexCCC
                                    className="align-items-start"
                                >
                                    <CustomText
                                        textAlign="start"
                                        color={AgentColorPallette.fontGrey}
                                        weight={400}
                                        size="13px"
                                        bottom="0"
                                        paddingTop={'10px'}
                                    >
                                        {item.name}
                                    </CustomText>
                                    <CustomText
                                        textAlign="start"
                                        color={AgentColorPallette.black}
                                        weight={400}
                                        size="13px"
                                        bottom="0"
                                        paddingTop={'5px'}
                                    >
                                        {item.value}
                                    </CustomText>
                                </DisplayFlexCCC>
                            </ProfileItemStyle>
                        ))}
                    </Grid>
                </ProfileContentCol>
            </>
        )
    }

    useEffect(() => {
        if (
            getDownloadEwDraftPdfStatus === "success" &&
            getDownloadEwDraftPdfData
        ) {
            downloadFile(getDownloadEwDraftPdfData.pdf_url)
            dispatchError(
                resetError({
                    getDownloadTravelDraftPdfStatus: "",
                })
            )
        }
    }, [
        getDownloadEwDraftPdfStatus,
        getDownloadEwDraftPdfData,
        dispatchError,
    ])

    const handleBuyInsuranceNow = () => {
        if (getCustomerEwDetailsData?.section === "mv_quote_summary") {
            history.push({
                pathname: `/customer/waiting/${id}`,
            })
        }
        else {
            history.push({
                pathname: `/extended_warranty/registration/${id}`,
            })
        }
    }

    const handleDownloadPdf = () => {
        if (id) {
            getEwDraftDownloadPdfReq({
                draftQuoteId: id,
            })
        }
    }

    return (
      <div>
        <MitraHeaderLogo src={QS_LOGO_PP}></MitraHeaderLogo>
        <CardHeaderCtn>
          <ImageCtn>
            {props?.provider?.logo_url && (
              <img
                src={props?.provider?.logo_url}
                width={48}
                height={20}
                alt="logo"
                lassName="logo-image"
              />
            )}
          </ImageCtn>
          <CardHeading textAlign="center">{props?.provider?.name}</CardHeading>
          {props?.package?.code === "extended-warranty-protection-bronze" && (
            <CardHeading2 textAlign="center" color="#C86400">
              {props?.package?.name}
            </CardHeading2>
          )}
          {props?.package?.code === "extended-warranty-protection-silver" && (
            <CardHeading2 textAlign="center" color="#666666">
              {props?.package?.name}
            </CardHeading2>
          )}
          {props?.package?.code === "extended-warranty-protection-gold" && (
            <CardHeading2 textAlign="center" color="#B4A000">
              {props?.package?.name}
            </CardHeading2>
          )}
          <DisplayFlexPP>
            <QuoteId>Quotation ID</QuoteId>
            <QuoteId>PPMitra-QS1234567890</QuoteId>
          </DisplayFlexPP>
        </CardHeaderCtn>
        <Hr />
        {renderProfileAgCards(
          getProductDetails(getCustomerEwDetailsData),
          "Detail Perlindungan"
        )}
        <Hr />
        {renderProfileAgCards(
          getCarDetails(getCustomerEwDetailsData),
          "Data Kendaraan"
        )}
        <Hr />
        {renderProfileAgCards(
          getAgentDetails(getCustomerEwDetailsData),
          "Data Agen"
        )}
        <Hr />
        {benefitsData && (
          <AccordionComponent
            section={getCustomerEwDetailsData.section}
            data={activeTabData.Manfaat}
            title="Daftar Manfaat"
          />
        )}
        <Hr />
        <CustomText weight={700} size="15px" color={AgentColorPallette.ppBlue}>
          {"Detail Transaksi"}
        </CustomText>
        <DisplayFlexRow>
          <PremiumnCal>Premi Dasar</PremiumnCal>
          <PremiumnCal>
            {formatMoney(
              getCustomerEwDetailsData?.policy_details?.package_data?.sub_total,
              0,
              "Rp"
            )}
          </PremiumnCal>
        </DisplayFlexRow>
        <DisplayFlexRow>
          <PremiumnCal>Biaya Materai</PremiumnCal>
          <PremiumnCal>
            {formatMoney(
              getCustomerEwDetailsData?.policy_details?.package_data
                ?.stamp_duty,
              0,
              "Rp"
            )}
          </PremiumnCal>
        </DisplayFlexRow>
        {getCustomerEwDetailsData?.policy_details?.discount > 0 && (
          <DisplayFlexRow>
            <PremiumnCal>Diskon</PremiumnCal>
            <PremiumnCal>
              {formatMoney(
                getCustomerEwDetailsData?.policy_details?.discount,
                0,
                "Rp"
              )}
            </PremiumnCal>
          </DisplayFlexRow>
        )}
        <Hr1 />
        <DisplayFlexRow>
          <TotalPreCal>Total Premi / 12 Bulan</TotalPreCal>
          <TotalPreCal>
            {formatMoney(
              getCustomerEwDetailsData?.policy_details?.package_data
                ?.total_bill -
                getCustomerEwDetailsData?.policy_details?.discount,
              0,
              "Rp"
            )}
          </TotalPreCal>
        </DisplayFlexRow>
        <Hr />
        <CustomerNoteStyle>
          <CustomText color={AgentColorPallette.black} bottom="4px">
            {LANG_STRINGS.note}:
          </CustomText>
          {CUSTOMER_NOTE.map((note, index) => (
            <CustomText
              key={`note_${index}`}
              color={AgentColorPallette.black}
              bottom="4px"
              lineHeight={1.5}
            >
              {`${index + 1}. ${note}`}
            </CustomText>
          ))}
        </CustomerNoteStyle>
        <Footer>
          <CustomText
            weight="700"
            size="9px"
            textAlign="center"
            color="#000000"
          >
            {LANG_STRINGS.OjkText}
          </CustomText>
          <img src={OJK_PP_BLACK} className="ojk-logo" alt="logo" />
        </Footer>
        <BtnContainerStyle>
          <Button
            className="select-buttons reject-button"
            onClick={handleDownloadPdf}
          >
            {LANG_STRINGS.downloadFile}
            <ButtonLogo src={NEW_DOWNLOAD_ICON} alt="" />
          </Button>
          <Button
            className="select-buttons next-button"
            onClick={handleBuyInsuranceNow}
          >
            {LANG_STRINGS.buyInsurance}
            <ButtonLogo src={NEW_ARROW_RIGHT} alt="" />
          </Button>
        </BtnContainerStyle>
      </div>
    );
}

export default PolicyDocumentDetails 
