import { useEffect, useState } from 'react'
import Accordion from './EwAccordion.js'
import { AccordionWrapper, AccordionHeading } from './index.style.js'

const AccordionComponent = ({ section, data = [], title = '' }) => {
  const [accData, setAccData] = useState(data)

  useEffect(() => {
    if (section === 'package_insurance') {
      const updatedData = accData.map((curr) => {
        return { heading: Object.values(curr)[2], title: Object.values(curr)[1], data: Object.values(curr)[3], url: Object.values(curr)[0] }
      })
    setAccData(updatedData)
    }
    else if (section === 'mv_quote_summary') {
      const updatedData = accData.map((curr) => {
        return { heading: Object.values(curr)[0], title: Object.values(curr)[1], data: Object.values(curr)[2], url: Object.values(curr)[3] }
      })
      setAccData(updatedData)
    }
  }, [])
  
  return (
      <AccordionWrapper>
        <AccordionHeading>
          {title}
        </AccordionHeading>
        {accData && accData.map((item, index) => {
          return (
            <>
              <Accordion heading ={item.heading} url={item.url} title={item.title} data={item.data} parentTitle={title} index={index}/>
            </>
          )
        })}
      </AccordionWrapper>
  )
}
export default AccordionComponent
