import { createContext, useContext, useReducer } from 'react'

export const ExtendedWarrantyContext = createContext()

export const ExtendedWarrantyContextProvider = ({ reducer, ...props }) => {
  return (
    <ExtendedWarrantyContext.Provider value={useReducer(reducer, {})}>
      {props.children}
    </ExtendedWarrantyContext.Provider>
  )
}

export const useExtendedWarrantyContextValue = () => useContext(ExtendedWarrantyContext)
